import {config,defaultState} from '../config/commission-config.js';
const round=x=>Math.round((x+Number.EPSILON)*100)/100;
const sum=a=>round(a.reduce((x,y)=>x+y,0));
export function validate(s,c=config){const errors=[]; const check=(k,min,max,int=false)=>{if(typeof s[k]!=='number'||!Number.isFinite(s[k])||s[k]<min||s[k]>max||(int&&!Number.isInteger(s[k])))errors.push(`${k}: enter ${int?'a whole number':'a number'} between ${min} and ${max}`)};
 check('deals',0,c.limits.deals,true);check('amount',0,c.limits.amount);check('growth',-25,c.limits.growth);check('ramp',0,36,true);check('capacity',0,c.limits.deals,true);check('retention',0,100);check('delay',0,12,true);check('expense',0,c.limits.expense);check('target',0,c.limits.target);for(const k of ['bonuses','recurring'])if(typeof s[k]!=='boolean')errors.push(`Invalid ${k} option`);if(![12,24,36].includes(s.horizon))errors.push('Invalid horizon');if(!c.scenarios.some(x=>x.id===s.scenario))errors.push('Invalid scenario');
 const products=c.products.filter(p=>p.eligible);let total=0;for(const p of products){const a=s.allocation?.[p.id],r=c.verificationStatus==='verified'?(p.method==='fixed'?p.fixed:p.rate):s.rates?.[p.id];if(!Number.isFinite(a)||a<0||a>100)errors.push(`Invalid allocation: ${p.name}`);else total+=a;if(!Number.isFinite(r)||r<0||r>(p.method==='percentage'?c.limits.rate:c.limits.amount))errors.push(`Invalid compensation: ${p.name}`);}if(Math.abs(total-100)>.00001)errors.push('Product allocations must total 100%.');for(const x of c.scenarios){const f=s.factors?.[x.id];if(!Number.isFinite(f)||f<0||f>3)errors.push(`Invalid scenario factor: ${x.name}`);}if(c.verificationStatus==='verified'&&(!c.approvedSource||!c.effectiveDate))errors.push('Verified mode requires an approved source and effective date.');return errors;}
export function tierFor(deals,c=config){return c.tiers.find(t=>deals>=t.min&&(t.max===null||deals<t.max+1))??c.tiers[0]}
export function calculate(s,c=config){const errors=validate(s,c);if(errors.length)throw new Error(errors.join('; '));const products=c.products.filter(p=>p.eligible);const rate=p=>c.verificationStatus==='verified'?(p.method==='fixed'?p.fixed:p.rate):s.rates[p.id];const factor=s.factors[s.scenario];const breakdown=deals=>products.map(p=>{const allocated=deals*s.allocation[p.id]/100;const volume=p.method==='fixed'?0:round(allocated*s.amount);return {id:p.id,name:p.name,deals:allocated,volume,rate:rate(p),method:p.method,commission:round(p.method==='fixed'?allocated*rate(p):volume*rate(p)/100)}});
 const production=m=>Math.min(s.capacity,s.deals*factor*(1+s.growth/100)**m*(s.ramp?Math.min(1,(m+1)/s.ramp):1));
 const rows=[];let cumulative=0,receiptTotal=0;let cohorts={};for(let m=0;m<36;m++){const deals=production(m),items=breakdown(deals),volume=sum(items.map(x=>x.volume));let recurring=0,bonus=0;
 if(s.recurring&&c.features.recurring)for(const r of c.recurring){const eligible=items.find(x=>x.id===r.productId)?.deals??0;cohorts[r.productId]=(cohorts[r.productId]??0)*s.retention/100+eligible;recurring+=cohorts[r.productId]*r.monthlyFee;}
 if(s.bonuses&&c.features.bonuses)for(const b of c.bonuses){if(deals>=b.minDeals&&volume>=(b.minVolume??0))bonus+=b.amount;}
 const gross=sum([...items.map(x=>x.commission),recurring,bonus]);const receipts=s.delay===0?gross:(rows[m-s.delay]?.gross??0);cumulative=round(cumulative+gross);receiptTotal=round(receiptTotal+receipts);rows.push({month:m+1,deals,volume,items,gross,recurring:round(recurring),bonus:round(bonus),receipts,expense:s.expense,operatingIncome:round(receipts-s.expense),cumulative,receiptTotal});}
 const current=rows[0];const tier=tierFor(current.deals,c);const next=c.tiers[c.tiers.indexOf(tier)+1];return {current,rows,annualized:round(current.gross*12),firstYear:rows[11].cumulative,threeYear:rows[35].cumulative,tier:tier.name,nextTier:next?.name??null,toNext:next?Math.max(0,Math.ceil(next.min-current.deals)):0};}
export function compare(s,c=config){return c.scenarios.map(x=>({name:x.name,id:x.id,...calculate({...s,scenario:x.id},c)}))}
export function targetDeals(s,c=config){if(s.target===0)return {deals:0,volume:0};for(let n=0;n<=c.limits.deals;n++){const v=calculate({...s,deals:n},c).current;if(v.gross>=s.target)return {deals:n,volume:v.volume,modeledDeals:v.deals};}return null;}
export function fromQuery(search,c=config){const base=defaultState(c);try{const raw=new URLSearchParams(search).get('s');if(!raw)return base;const obj=JSON.parse(raw);if(!obj||typeof obj!=='object')return base;const state=Object.fromEntries(Object.keys(base).map(k=>[k,Object.hasOwn(obj,k)?obj[k]:base[k]]));for(const key of ['allocation','rates','factors'])state[key]=Object.fromEntries(Object.keys(base[key]).map(k=>[k,state[key]?.[k]]));return validate(state,c).length?base:state;}catch{return base;}}
